<?php declare(strict_types=1); require_once '/var/www/glitchahitch/config/db.php'; require_once '/var/www/glitchahitch/lib/session.php'; require_once '/var/www/glitchahitch/lib/auth.php'; use function App\Auth\{require_admin,csrf_token}; start_secure_session();require_admin();$pdo=db();$csrf=csrf_token();$rows=$pdo->query("SELECT setting_key,setting_value FROM whatsapp_bridge_settings")->fetchAll(PDO::FETCH_KEY_PAIR);$on=fn($k,$d=false)=>($rows[$k]??($d?'1':'0'))==='1';$v=fn($k,$d)=>$rows[$k]??$d;$defaults=['looking'=>'looking,need,request','offering'=>'offering,offer,drive,available','from'=>'from','to'=>'to','going_to'=>'going to,going-to','call'=>'call','whatsapp'=>'whatsapp','note'=>'note']; ?>
<!doctype html><html><head><meta charset="utf-8"><title>WhatsApp Workflow</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><a href="/admin/index.php">← Admin</a><h1 class="h3 mt-3">WhatsApp workflow controls</h1><form id="workflow"><div class="row g-3"><section class="col-md-4"><div class="card h-100"><div class="card-body"><h2 class="h5">1. Trigger</h2><label class="form-check"><input class="form-check-input" type="checkbox" name="trigger_mention" <?=$on('trigger_mention',true)?'checked':''?>> <code>@ridebot</code> mention</label><label class="form-check"><input class="form-check-input" type="checkbox" name="trigger_all_group" <?=$on('trigger_all_group')?'checked':''?>> Any group message</label><label class="form-check"><input class="form-check-input" type="checkbox" name="trigger_confirm" <?=$on('trigger_confirm',true)?'checked':''?>> CONFIRM / CANCEL DM</label></div></div></section><section class="col-md-4"><div class="card h-100"><div class="card-body"><h2 class="h5">2. Wait condition</h2><label class="form-check"><input class="form-check-input" type="checkbox" name="condition_format" <?=$on('condition_format',true)?'checked':''?>> Format is complete</label><label class="form-check"><input class="form-check-input" type="checkbox" name="condition_confirm" <?=$on('condition_confirm',true)?'checked':''?>> User confirmation</label></div></div></section><section class="col-md-4"><div class="card h-100"><div class="card-body"><h2 class="h5">3. Actions</h2><label class="form-check"><input class="form-check-input" type="checkbox" name="action_private_dm" <?=$on('action_private_dm',true)?'checked':''?>> Private DM</label><label class="form-check"><input class="form-check-input" type="checkbox" name="action_queue" <?=$on('action_queue',true)?'checked':''?>> Admin queue</label><label class="form-check"><input class="form-check-input" type="checkbox" name="action_post_group" <?=$on('action_post_group',true)?'checked':''?>> Post to group</label><label class="form-check"><input class="form-check-input" type="checkbox" name="action_create_ride" <?=$on('action_create_ride',true)?'checked':''?>> Create public Bot ride</label></div></div></section></div><section class="card mt-3"><div class="card-body"><h2 class="h5">Keywords and format</h2><p class="text-secondary small">Separate alternate keywords with commas.</p><div class="row g-2"><?php foreach($defaults as $k=>$default): ?><div class="col-md-3"><label class="form-label"><?=ucwords(str_replace('_',' ',$k))?></label><input class="form-control" name="keyword_<?=$k?>" value="<?=htmlspecialchars($v('keyword_'.$k,$default))?>"></div><?php endforeach; ?><div class="col-12"><label class="form-label">Help message sent by the bot</label><textarea class="form-control" name="format_help" rows="2"><?=htmlspecialchars($v('format_help','@ridebot Looking from Kingston to Montego Bay call: 876-555-1234 whatsapp: 876-555-9999 note: Need to arrive before 5 PM.'))?></textarea></div></div></div></section><button class="btn btn-primary mt-3">Save workflow</button> <span id="result" class="ms-2"></span></form></main><script>document.querySelector('form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.csrf='<?=htmlspecialchars($csrf)?>';let r=await fetch('/api/admin/whatsapp_workflow.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});document.querySelector('#result').textContent=r.ok?'Saved':'Error saving'}</script></body></html>
